/** The dumper's output for this port. */
std::string dump() {
    std::string sb;
    auto opm = upstreamModel();
    auto g = grid(opm.get(), 2, 0.0);
    for (int k = 0; k < 3; k++)
        plane(sb, "f2 foc0 grid" + std::to_string(k), g.grid[static_cast<std::size_t>(k)]);
    plane(sb, "f2 foc0.05 opd", grid(opm.get(), 2, 0.05).grid[2]);
    plane(sb, "f1 foc0.05 opd", grid(opm.get(), 1, 0.05).grid[2]);
    plane(sb, "f0 foc0.05 opd", grid(opm.get(), 0, 0.05).grid[2]);

    TraceOptions options;
    options.check_apertures = true;
    auto &fld = *opm->optical_spec->fov->fields[2];
    auto eval = Analyses::eval_wavefront(opm.get(), fld, opm->optical_spec->wvls->central_wvl(),
                                         0.0, std::nullopt, std::nullopt, 20, NaN, 1.0, options);
    std::vector<std::vector<double>> ev(20, std::vector<double>(20));
    for (std::size_t i = 0; i < 20; i++)
        for (std::size_t j = 0; j < 20; j++) ev[i][j] = eval[i][j][2];
    plane(sb, "eval f2 opd", ev);

    auto AP = Analyses::calc_psf(grid(opm.get(), 2, 0.0).grid[2], 20, 64);
    std::vector<std::vector<double>> win(9, std::vector<double>(9));
    for (std::size_t i = 0; i < 9; i++)
        for (std::size_t j = 0; j < 9; j++) win[i][j] = AP[28 + i][28 + j];
    plane(sb, "psf f2 window 28..36", win);
    auto AP0 = Analyses::calc_psf(grid(opm.get(), 0, 0.05).grid[2], 20, 64);
    sb += "psf f0 foc0.05 [39][25]=" + redukti::doubleToString(AP0[39][25]) + '\n';
    auto s = grid(opm.get(), 2, 0.0).calc_psf_scaling(64);
    sb += "scaling=" + redukti::doubleToString(s[0]) + "," + redukti::doubleToString(s[1]) + '\n';
    return sb;
}

