TEST(analyses_ray_grid_reproduces_upstream_opd) {
    auto opm = upstreamModel();
    auto focused = grid(opm.get(), 2, 0.0);
    CHECK_CLOSE(focused.grid[0][0][0], -0.8109431712108661, 1e-15);
    CHECK_CLOSE(focused.grid[1][0][0], -0.477476674867249, 1e-15);
    CHECK_CLOSE(focused.grid[2][10][10], 0.015908313797373393, 1e-13);

    auto defocused = grid(opm.get(), 2, 0.05);
    CHECK_CLOSE(defocused.grid[2][3][15], 1.1270749042956802, 1e-12);
    // Clipped by an aperture, as upstream
    CHECK(std::isnan(grid(opm.get(), 1, 0.05).grid[2][0][10]));
}

TEST(analyses_eval_wavefront_agrees_with_the_refocused_grid) {
    auto opm = upstreamModel();
    auto focused = grid(opm.get(), 2, 0.0);
    TraceOptions options;
    options.check_apertures = true;
    auto &fld = *opm->optical_spec->fov->fields[2];
    auto eval = Analyses::eval_wavefront(opm.get(), fld, opm->optical_spec->wvls->central_wvl(),
                                         0.0, std::nullopt, std::nullopt, 20, NaN, 1.0, options);
    CHECK_CLOSE(eval[10][10][2], 0.015908313797373393, 1e-13);
    for (std::size_t i = 0; i < 20; i++)
        for (std::size_t j = 0; j < 20; j++)
            if (!(std::isnan(focused.grid[2][i][j]) && std::isnan(eval[i][j][2])))
                CHECK_CLOSE(eval[i][j][2], focused.grid[2][i][j], 1e-12);
}

TEST(analyses_calc_psf_reproduces_upstream) {
    auto opm = upstreamModel();
    auto AP = Analyses::calc_psf(grid(opm.get(), 2, 0.0).grid[2], 20, 64);
    CHECK_CLOSE(AP[32][32], 0.44459091011809493, 1e-13);
    CHECK_CLOSE(AP[30][35], 0.3075630882612663, 1e-13);
    auto defocused = Analyses::calc_psf(grid(opm.get(), 0, 0.05).grid[2], 20, 64);
    CHECK_CLOSE(defocused[39][25], 0.8138388544390374, 1e-13);

    auto scaling = grid(opm.get(), 2, 0.0).calc_psf_scaling(64);
    CHECK_CLOSE(scaling[0], 1.3004005879190803, 1e-15);
    CHECK_CLOSE(scaling[1], 0.00041164120903762653, 1e-18);
}

TEST(analyses_match_jvm) {
    auto got = split(dump(), '\n');
    auto want = split(EXPECTED, '\n');
    CHECK_EQ(got.size(), want.size());
    bool psf = false;
    for (std::size_t i = 0; i < got.size() && i < want.size(); i++) {
        auto a = split(got[i], ',');
        auto e = split(want[i], ',');
        CHECK_EQ(a.size(), e.size());
        if (a.size() == 1 || got[i].find('=') != std::string::npos) {
            psf = got[i].rfind("psf", 0) == 0;
            if (psf && got[i].find('=') != std::string::npos) {
                // psf f0 foc0.05 [39][25]=value
                auto at = got[i].find('=');
                CHECK_STR_EQ(got[i].substr(0, at), want[i].substr(0, want[i].find('=')));
                CHECK_CLOSE(std::stod(got[i].substr(at + 1)),
                            std::stod(want[i].substr(want[i].find('=') + 1)), 1e-13);
                psf = false;
            } else {
                CHECK_STR_EQ(got[i], want[i]);
            }
            continue;
        }
        for (std::size_t k = 0; k < a.size() && k < e.size(); k++) {
            if (psf)
                CHECK_CLOSE(std::stod(a[k]), std::stod(e[k]), 1e-13);
            else
                CHECK_STR_EQ(a[k], e[k]);
        }
    }
}

TEST(analyses_calc_psf_rejects_an_odd_grid_as_numpy_does) {
    std::vector<std::vector<double>> wavefront(21, std::vector<double>(21));
    CHECK_THROWS(Analyses::calc_psf(wavefront, 21, 64), redukti::IllegalArgumentException);
}

TEST(analyses_calc_psf_preserves_zero_opd_and_piston_invariance) {
    std::vector<std::vector<double>> wavefront(4, std::vector<double>(4));
    for (int i = 0; i < 4; i++)
        for (int j = 0; j < 4; j++)
            wavefront[static_cast<std::size_t>(i)][static_cast<std::size_t>(j)] =
                (i == 0 || j == 0) ? NaN : (i - j) * 0.125;
    auto original = Analyses::calc_psf(wavefront, 4, 8);
    for (auto &row : wavefront)
        for (auto &w : row) w += 0.03125;
    auto shifted = Analyses::calc_psf(wavefront, 4, 8);
    for (std::size_t i = 0; i < 8; i++)
        for (std::size_t j = 0; j < 8; j++)
            CHECK_CLOSE(shifted[i][j], original[i][j], 1e-14);
    std::vector<std::vector<double>> flat(4, std::vector<double>(4));
    CHECK_CLOSE(Analyses::calc_psf(flat, 4, 8)[4][4], 1.0, 1e-14);
}

TEST(analyses_calc_psf_rejects_an_empty_pupil) {
    std::vector<std::vector<double>> wavefront(4, std::vector<double>(4, NaN));
    CHECK_THROWS(Analyses::calc_psf(wavefront, 4, 8), redukti::IllegalArgumentException);
}

TEST(analyses_psf_sampling_matches_upstream) {
    auto a = Analyses::psf_sampling(std::nullopt, 20, 7);
    CHECK(a[0] == 57 && a[1] == 20 && a[2] == 7);
    auto b = Analyses::psf_sampling(64, std::nullopt, 5);
    CHECK(b[0] == 64 && b[1] == 31 && b[2] == 5);
    auto c = Analyses::psf_sampling(64, 25, std::nullopt);
    CHECK(c[0] == 64 && c[1] == 25 && c[2] == 6);
    CHECK_THROWS(Analyses::psf_sampling(64, 25, 6), redukti::IllegalArgumentException);
}
